type agreementDiscardedCodeDiagnosticSingle struct {
	Field, Index, Start int
	Body                string
	Diagnostics         []render.Diagnostic
}
type agreementDiscardedCodeDiagnosticWitness struct {
	Name, Body, Target, Selected    string
	Diagnostics, PrivateDiagnostics []render.Diagnostic
	Indices                         []int
	Singles                         []agreementDiscardedCodeDiagnosticSingle
}

func agreementDiscardedCodeDiagnosticOwners(native agreementNativeOwnerSource, check *agreementNativeCheckSource, tree *agreementNativeProseAddressTree, target string) ([]agreementMixedUnusedOwner, bool) {
	if !tree.Valid || target == "" {
		return nil, false
	}
	var owners []agreementMixedUnusedOwner
	codeOwned := false
	used := make(map[graph.Span]bool)
	for fi, field := range check.Fields {
		if field.Comment || field.Escaped || field.DefinitionOwner < 0 || !slices.Contains(field.Targets, target) {
			continue
		}
		if len(field.Targets) != 1 || field.DefinitionOwner >= len(native.Definitions) || used[field.Span] {
			return nil, false
		}
		definition := &native.Definitions[field.DefinitionOwner]
		if definition.Span.Start < 0 || definition.Span.Stop <= definition.Span.Start || field.Span.Start < definition.Span.Start || field.Span.Stop > definition.Span.Stop || field.Span.Stop <= field.Span.Start || definition.Name.Start < definition.Span.Start || definition.Name.Stop > definition.Span.Stop {
			return nil, false
		}
		candidate := -1
		for di := range tree.Definitions {
			d := &tree.Definitions[di]
			if !d.Found || d.Root != field.DefinitionOwner+1 || d.Root >= len(tree.Trees) || d.Root < 1 || d.Node != 0 || len(tree.Trees[d.Root]) == 0 || tree.Trees[d.Root][0].Kind != extast.KindFootnote.String() || d.Label != definition.Label || d.Bounds.Parent != definition.Parent || d.Bounds.Span != definition.Span || d.Bounds.Label != definition.Name {
				continue
			}
			if candidate >= 0 {
				return nil, false
			}
			candidate = di
		}
		if candidate < 0 {
			return nil, false
		}
		used[field.Span] = true
		codeOwned = codeOwned || field.Code
		d := &tree.Definitions[candidate]
		owners = append(owners, agreementMixedUnusedOwner{Field: fi, Definition: field.DefinitionOwner, Root: d.Root, Node: d.Node})
	}
	return owners, len(owners) > 0 && codeOwned
}

// Only the selected target bytes change; unrelated citations retain their spelling.
func agreementDiscardedCodeDiagnosticPrivate(body, target string, native agreementNativeOwnerSource, check *agreementNativeCheckSource, tree *agreementNativeProseAddressTree) (string, []agreementMixedRename, bool) {
	if strings.Contains(body, "q") {
		return "", nil, false
	}
	owners, ok := agreementDiscardedCodeDiagnosticOwners(native, check, tree, target)
	if !ok {
		return "", nil, false
	}
	private := []byte(body)
	var changes []agreementMixedRename
	for _, owner := range owners {
		field := &check.Fields[owner.Field]
		if field.Span.Start < 0 || field.Span.Stop > len(body) || field.Span.Stop <= field.Span.Start || len(field.Word) < 4 || !strings.HasPrefix(field.Word, "[[") || !strings.HasSuffix(field.Word, "]]") || body[field.Span.Start:field.Span.Stop] != field.Word || native.Definitions[owner.Definition].Span.Stop > len(body) {
			return "", nil, false
		}
		inner := field.Word[2 : len(field.Word)-2]
		link, valid := graph.ParseWikilink(inner)
		if !valid || link.Target != target || strings.ContainsAny(inner, "[]\r\n") || strings.ContainsRune(inner, 96) {
			return "", nil, false
		}
		start := field.Span.Start + 2 + strings.Index(inner, link.Target)
		stop := start + len(target)
		if start < field.Span.Start+2 || stop > field.Span.Stop-2 || body[start:stop] != target {
			return "", nil, false
		}
		replacement := strings.Repeat("q", len(target))
		copy(private[start:stop], replacement)
		changes = append(changes, agreementMixedRename{Field: owner.Field, Span: graph.Span{Start: start, Stop: stop}, Old: target, New: replacement})
	}
	return string(private), changes, len(changes) > 0
}

func agreementDiscardedCodeDiagnosticSource(body, target string) (*agreementSharedUnusedWitness, *agreementSharedUnusedVariant, bool) {
	witnesses := agreementDiscardedCodeDiagnosticSources()
	for wi := range witnesses {
		w := &witnesses[wi]
		if w.Body != body {
			continue
		}
		for vi := range w.Variants {
			v := &w.Variants[vi]
			if v.Target == target {
				return w, v, true
			}
		}
		return nil, nil, false
	}
	return nil, nil, false
}

// Every changed diagnostic belongs to one declared discarded field.
func agreementDiscardedCodeDiagnosticDifference(c agreementCase, f *agreementFailure, raw string, page *agreementHTML, diagnostics []render.Diagnostic, failures []agreementFailure) (kind, authority, wrong string) {
	if f == nil || page == nil || c.Title != "" || len(c.Companions) != 0 || f.Property != "P0" || f.Identity != "diagnostic-html" || f.Direction != "diagnostic-only" || f.Multiplicity < 1 || f.Tuple.SourceRole != "" || f.Tuple.State != "wikilink-broken" || f.Tuple.Section != "" || f.Fragment != "" || f.Cut != "" || f.PagePresent || f.JudgeAccepted || f.ExcerptFound {
		return "", "", ""
	}
	records := agreementDiscardedCodeDiagnosticWitnesses()
	for ri := range records {
		r := &records[ri]
		if c.Body != r.Body || f.Tuple.Target != r.Target {
			continue
		}
		if agreementSignature(f) != r.Selected || !cmp.Equal(diagnostics, r.Diagnostics) {
			return "", "", ""
		}
		w, v, found := agreementDiscardedCodeDiagnosticSource(c.Body, r.Target)
		if !found {
			return "", "", ""
		}
		native := agreementNativeOwnerReading(c.Body)
		check := agreementNativeCheckReading(c.Body, native)
		tree := agreementNativeProseAddressTreeReading(c.Body, nil)
		parts, pok := agreementCodeWindowParts(raw)
		owners, ok := agreementDiscardedCodeDiagnosticOwners(native, &check, &tree, r.Target)
		private, changes, valid := agreementDiscardedCodeDiagnosticPrivate(c.Body, r.Target, native, &check, &tree)
		if !pok || !ok || !valid || len(owners) != f.Multiplicity || len(r.Indices) != len(owners) || !cmp.Equal(owners, v.Owners) || !cmp.Equal(changes, v.Changes) || private != v.Body || !cmp.Equal(native, w.Native) || !cmp.Equal(check, w.Check) || !cmp.Equal(tree, w.Tree) || !cmp.Equal(agreementNativeCodePayloadSites(c.Body), w.Sites) || !cmp.Equal(agreementNativeHTMLAddressSites(c.Body), w.HTML) || !cmp.Equal(judge.LinkTargets(c.Body), w.Targets) || !cmp.Equal(parts, w.Parts) || !cmp.Equal(*page, w.Page) || !maps.Equal(agreementMixedCurrent(failures), w.Signatures) {
			return "", "", ""
		}
		return "debt", "#1011 stage 5", "page-diagnostic"
	}
	return "", "", ""
}

